def sigmaNat (n : Nat) : Nat := (Finset.Icc 1 n).sum id
 def sol (a b : Nat) : Bool := decide (0 < a ∧ 0 < b ∧ sigmaNat a + sigmaNat b = sigmaNat (a + b))
 def orderedSolutions : List (Nat × Nat) := [(1,1),(1,2),(2,1),(1,4),(4,1),(1,6),(6,1),(2,3),(3,2),(1,10),(10,1),(2,6),(6,2),(3,6),(6,3),(1,18),(18,1),(2,12),(12,2),(3,15),(15,3),(4,8),(8,4),(6,12),(12,6),(9,15),(15,9)]
 def checkFiniteCore : Bool := decide ((orderedSolutions.length = 27) ∧ (∀ p ∈ orderedSolutions, p.1 + p.2 ≤ 40 ∧ sol p.1 p.2 = true) ∧ (∀ a b : Nat, 0 < a → 0 < b → a + b ≤ 40 → sol a b = true → (a,b) ∈ orderedSolutions))

