def sigmaNat (n : Nat) : Nat := ∑ d in (Finset.divisors n), d

def isSolution (a b : Nat) : Bool := decide (0 < a ∧ 0 < b ∧ a + b ≤ 20 ∧ sigmaNat a + sigmaNat b = sigmaNat (a + b))

def solutionCount : Nat := (Finset.Icc 1 20 ×ˢ Finset.Icc 1 20).filter (fun p => isSolution p.1 p.2).card

def sigma (n : Nat) : Nat := (Finset.divisors n).sum id

def isSolution (a b : Nat) : Bool :=
  decide (1 ≤ a ∧ 1 ≤ b ∧ a + b ≤ 20 ∧ sigma a + sigma b = sigma (a + b))

def solutionCount : Nat :=
  ((Finset.Icc 1 20).product (Finset.Icc 1 20)).filter (fun p => isSolution p.1 p.2)).card

